      const code = response.getResponseCode();
      const parsed = JSON.parse(response.getContentText() || '{}');
      if (code < 200 || code >= 300) throw new Error('HTTP ' + code + ': ' + ((parsed.error && parsed.error.message) || 'permintaan ditolak'));
